
# BTC dashboard weekly refresh kit. Usage:
#   python3 -I refresh_kit.py BTC_DAILY_CSV FGI_4H_CSV OUTDIR [PREVDIR]
# Writes every dashboard JSON into OUTDIR and alerts.txt (what flipped vs PREVDIR).
import sys, os, json, subprocess
SCRIPTS = {"make_dash_data.py": "import sys, json, pandas as pd, numpy as np, importlib.util, io, contextlib\nsrc_csv, outdir = sys.argv[1], sys.argv[2]\ncode = open(__file__).read()\nd = pd.read_csv(src_csv, parse_dates=['date']).set_index('date').close\nasof = d.index[-1].strftime('%Y-%m-%d')\nmeta = [{\"label\": \"make_dash_data.py\", \"value\": code, \"type\": \"code\", \"lang\": \"python\"},\n        {\"label\": \"Input\", \"value\": \"btc-usd-daily.csv (Bitstamp daily closes via github.com/rcaljouw/btc-price-history)\"},\n        {\"label\": \"Data up to\", \"value\": asof}]\ndef dump(name, rows):\n    json.dump({\"rows\": rows, \"meta\": meta}, open(f\"{outdir}/{name}.json\", \"w\"))\nw = d.resample('W-SUN').last()\nma200 = d.rolling(200).mean(); ma20w = w.rolling(20).mean()\nprice = float(d.iloc[-1])\nhi50, lo25 = d.rolling(50).max().shift(), d.rolling(25).min().shift()\npos = np.zeros(len(d))\nfor i in range(1, len(d)):\n    pos[i] = 1 if d.iloc[i] > hi50.iloc[i] else (0 if d.iloc[i] < lo25.iloc[i] else pos[i-1])\nsig = [\n (\"20-week average\", \"Weekly close above its 20-week average\", float(ma20w.iloc[-1])),\n (\"200-day average\", \"Daily close above its 200-day average\", float(ma200.iloc[-1])),\n (\"Golden cross\", \"50-day average above 200-day average\", float(d.rolling(50).mean().iloc[-1])),\n (\"12-month momentum\", \"Price above where it was a year ago\", float(d.iloc[-366])),\n (\"50-day breakout\", \"In after a new 50-day high, out after a 25-day low\", float(hi50.iloc[-1]) if pos[-1]==0 else float(lo25.iloc[-1])),\n]\nrows = []\nfor name, desc, level in sig:\n    if name == \"Golden cross\":\n        inn = bool(d.rolling(50).mean().iloc[-1] > ma200.iloc[-1]); gap = (d.rolling(50).mean().iloc[-1]/ma200.iloc[-1]-1)*100\n        lvl = float(ma200.iloc[-1])\n    elif name == \"50-day breakout\":\n        inn = bool(pos[-1]==1); lvl = level; gap = (price/lvl-1)*100\n    else:\n        inn = price > level; lvl = level; gap = (price/lvl-1)*100\n    rows.append({\"rule\": name, \"how\": desc, \"level\": round(lvl), \"price\": round(price), \"gap_pct\": round(float(gap),1), \"state\": \"IN\" if inn else \"OUT\", \"in\": 1 if inn else 0, \"asof\": asof})\ndump(\"signals\", rows)\n# weekly history since 2014\nh = pd.DataFrame({\"close\": w, \"ma20w\": ma20w, \"ma200d\": ma200.resample('W-SUN').last()})['2014-01-01':]\nh[\"in20w\"] = (h.close > h.ma20w).astype(int)\nhist = [{\"week\": i.strftime('%Y-%m-%d'), \"close\": round(float(r.close)), \"ma20w\": round(float(r.ma20w)), \"ma200d\": round(float(r.ma200d)), \"in20w\": int(r.in20w)} for i, r in h.iterrows()]\ndump(\"history\", hist)\n# backtests\nret = d.pct_change().fillna(0)\nS = {\"Buy & hold\": pd.Series(1, index=d.index),\n     \"20-week average\": (w > ma20w).astype(int).reindex(d.index, method='ffill').fillna(0),\n     \"200-day average\": (d > ma200).astype(int),\n     \"Golden cross\": (d.rolling(50).mean() > ma200).astype(int),\n     \"12-month momentum\": (d > d.shift(365)).astype(int),\n     \"50-day breakout\": pd.Series(pos, index=d.index)}\nbt = []\nfor per, a, b in ((\"2014\u20132019\", \"2014-01-01\", \"2019-12-31\"), (\"2020\u2013now\", \"2020-01-01\", None)):\n    for k, s in S.items():\n        p = s.shift(1).fillna(0); r = (p*ret - p.diff().abs().fillna(0)*0.002)[a:b]\n        eq = (1+r).cumprod(); yrs = len(r)/365\n        bt.append({\"rule\": k, \"period\": per, \"return_pa\": round(100*(eq.iloc[-1]**(1/yrs)-1)), \"worst_drop\": round(100*(eq/eq.cummax()-1).min()), \"time_in\": round(100*p[a:b].mean())})\ndump(\"backtest\", bt)\n# Strat weekly 2-2-2 bear vs any 2d bar\nwk = d.resample('W-SUN').agg(['first']).iloc[:,0]\nD = pd.read_csv(src_csv, parse_dates=['date']).set_index('date')\nW = D.resample('W-SUN').agg({'high':'max','low':'min','close':'last'}).dropna()\nup, dn = W.high > W.high.shift(), W.low < W.low.shift()\nt = np.where(up & dn, '3', np.where(up, '2u', np.where(dn, '2d', '1')))\nst = []\nfor name, L in ((\"Three 2-down weeks in a row (2-2-2 bear)\", 3), (\"Any 2-down week (comparison)\", 1)):\n    idx = [i for i in range(L, len(W)-12) if all(t[i-k] == '2d' for k in range(L))]\n    nl = np.mean([W.low.iloc[i+1] < W.low.iloc[i] for i in idx])\n    l1 = np.mean([W.close.iloc[i+1] < W.close.iloc[i] for i in idx])\n    l12 = np.mean([W.close.iloc[i+12] < W.close.iloc[i] for i in idx])\n    st.append({\"setup\": name, \"times\": len(idx), \"next_week_lower_low_pct\": round(100*nl), \"lower_1w_pct\": round(100*l1), \"lower_12w_pct\": round(100*l12)})\ndump(\"strat\", st)\nprint(json.dumps(rows, indent=0)); print(st); print(len(hist))\n", "make_gauge.py": "import sys, json, pandas as pd, numpy as np\nsrc_csv, outdir = sys.argv[1], sys.argv[2]\ncode = open(__file__).read()\nd = pd.read_csv(src_csv, parse_dates=['date']).set_index('date').close\nasof = d.index[-1].strftime('%Y-%m-%d')\nmeta = [{\"label\": \"make_gauge.py\", \"value\": code, \"type\": \"code\", \"lang\": \"python\"},\n        {\"label\": \"Input\", \"value\": \"btc-usd-daily.csv (Bitstamp daily closes via github.com/rcaljouw/btc-price-history)\"},\n        {\"label\": \"Data up to\", \"value\": asof}]\ndef dump(name, rows): json.dump({\"rows\": rows, \"meta\": meta}, open(f\"{outdir}/{name}.json\", \"w\"))\n# --- inputs (all use only past/current data) ---\nma200 = d.rolling(200).mean(); ma50 = d.rolling(50).mean()\nw = d.resample('W-SUN').last()\n# live 20-week average: the 19 completed weeks before this one + today's price\nwkend = d.index + pd.offsets.Week(weekday=6) * 0\nwkend = pd.DatetimeIndex([x if x.weekday() == 6 else x + pd.Timedelta(days=6 - x.weekday()) for x in d.index])\nprev19 = w.rolling(19).sum().shift(1)\nma20w = pd.Series((prev19.reindex(wkend).values + d.values) / 20, index=d.index)\nwclose = d\nhi50, lo25 = d.rolling(50).max().shift(), d.rolling(25).min().shift()\npos = np.zeros(len(d))\nfor i in range(1, len(d)): pos[i] = 1 if d.iloc[i] > hi50.iloc[i] else (0 if d.iloc[i] < lo25.iloc[i] else pos[i-1])\nbrk = pd.Series(pos, index=d.index)\n# weekly RSI(14), Wilder\ndelta = w.diff(); up = delta.clip(lower=0).ewm(alpha=1/14, adjust=False).mean(); dn = (-delta.clip(upper=0)).ewm(alpha=1/14, adjust=False).mean()\nrsi_w = 100 - 100/(1+up/dn)  # last row = current (part) week\nrsi = rsi_w.reindex(d.index, method='ffill')\nrsi.iloc[-1] = rsi_w.iloc[-1]  # today's reading uses this week so far\nmayer = d / ma200\nath = d.cummax(); dd = d/ath - 1\nma200w = w.rolling(200).mean().reindex(d.index, method='ffill')\nlin = lambda x, a, b: ((x - a)/(b - a)*2 - 1).clip(-1, 1)   # maps a -> -1, b -> +1\ncomp = {\n # trend: +1 = bullish trend, -1 = bearish\n \"20-week average\":  (\"Trend\", np.where(wclose > ma20w, 1, -1), \"Price above / below its 20-week average\"),\n \"200-day average\":  (\"Trend\", np.where(d > ma200, 1, -1), \"Price above / below its 200-day average\"),\n \"Golden cross\":     (\"Trend\", np.where(ma50 > ma200, 1, -1), \"50-day average above / below the 200-day\"),\n \"12-month momentum\":(\"Trend\", np.where(d > d.shift(365), 1, -1), \"Price higher / lower than a year ago\"),\n \"50-day breakout\":  (\"Trend\", np.where(brk == 1, 1, -1), \"Last broke a 50-day high (in) or 25-day low (out)\"),\n # value / stretch: +1 = cheap (buy zone), -1 = stretched (sell zone)\n \"Mayer multiple\":   (\"Value\", -lin(mayer, 0.8, 2.4), \"Price \u00f7 200-day average. Under 0.8 cheap, over 2.4 stretched\"),\n \"Weekly RSI\":       (\"Value\", -lin(rsi, 30, 70), \"Momentum oscillator. Under 30 oversold, over 70 overbought\"),\n \"Drop from peak\":   (\"Value\", -lin(dd, -0.75, 0.0), \"How far below the all-time high. Deeper = cheaper\"),\n}\nS = pd.DataFrame({k: pd.Series(v[1], index=d.index, dtype=float) for k, v in comp.items()})\nvalid = d.index >= '2014-01-01'\ntrend = S[[k for k in comp if comp[k][0]=='Trend']].mean(axis=1)\nvalue = S[[k for k in comp if comp[k][0]=='Value']].mean(axis=1)\nscore = (100*(trend + value)/2)\ndef zone(s): return \"Strong sell\" if s <= -60 else \"Sell\" if s <= -20 else \"Neutral\" if s < 20 else \"Buy\" if s < 60 else \"Strong buy\"\nraw = {\"20-week average\": (float(wclose.iloc[-1]), float(ma20w.iloc[-1])), \"200-day average\": (float(d.iloc[-1]), float(ma200.iloc[-1])),\n       \"Golden cross\": (float(ma50.iloc[-1]), float(ma200.iloc[-1])), \"12-month momentum\": (float(d.iloc[-1]), float(d.iloc[-366])),\n       \"50-day breakout\": (float(d.iloc[-1]), float(hi50.iloc[-1]))}\nreading = {\"Mayer multiple\": f\"{mayer.iloc[-1]:.2f}\", \"Weekly RSI\": f\"{rsi.iloc[-1]:.0f}\", \"Drop from peak\": f\"{100*dd.iloc[-1]:.0f}%\"}\ncomps = []\nfor k, (grp, _, how) in comp.items():\n    v = float(S[k].iloc[-1])\n    rd = reading.get(k) or (\"IN\" if v > 0 else \"OUT\")\n    comps.append({\"signal\": k, \"group\": grp, \"score\": round(100*v), \"reading\": rd, \"how\": how,\n                  \"verdict\": \"Buy\" if v >= 0.2 else \"Sell\" if v <= -0.2 else \"Neutral\"})\npd.DataFrame({'score': score, 'trend': 100*trend, 'value': 100*value}).to_csv(f\"{outdir}/gauge_daily.csv\")\ndump(\"gauge_parts\", comps)\ncur = [{\"gauge\": \"Overall\", \"score\": round(float(score.iloc[-1])), \"zone\": zone(score.iloc[-1]), \"asof\": asof},\n       {\"gauge\": \"Trend\", \"score\": round(100*float(trend.iloc[-1])), \"zone\": zone(100*trend.iloc[-1]), \"asof\": asof},\n       {\"gauge\": \"Value\", \"score\": round(100*float(value.iloc[-1])), \"zone\": zone(100*value.iloc[-1]), \"asof\": asof}]\ndump(\"gauge_now\", cur)\n# weekly history (sample each Sunday close) and forward 12-week returns per zone\nwk = pd.DataFrame({\"close\": d, \"score\": score, \"trend\": 100*trend, \"value\": 100*value})[valid].resample('W-SUN').last().dropna()\nwk[\"fwd12\"] = wk.close.shift(-12)/wk.close - 1\nhist = [{\"week\": (i - pd.Timedelta(days=6)).strftime('%Y-%m-%d'), \"score\": round(float(r.score)), \"close\": round(float(r.close))} for i, r in wk.iterrows()]\ndump(\"gauge_history\", hist)\nzs = [\"Strong sell\", \"Sell\", \"Neutral\", \"Buy\", \"Strong buy\"]\nwk[\"zone\"] = wk.score.map(zone); ev = wk.dropna(subset=[\"fwd12\"])\nbase_med = ev.fwd12.median()\nbk = []\nfor z in zs:\n    e = ev[ev.zone == z]\n    bk.append({\"zone\": z, \"weeks\": int(len(e)), \"median_12w_pct\": round(100*float(e.fwd12.median()), 1) if len(e) else None,\n               \"up_12w_pct\": round(100*float((e.fwd12 > 0).mean())) if len(e) else None})\nbk.append({\"zone\": \"All weeks (baseline)\", \"weeks\": int(len(ev)), \"median_12w_pct\": round(100*float(base_med), 1), \"up_12w_pct\": round(100*float((ev.fwd12 > 0).mean()))})\ndump(\"gauge_zones\", bk)\n# robustness: split halves\nfor lab, a, b in ((\"2014-19\", \"2014\", \"2019\"), (\"2020-now\", \"2020\", \"2026\")):\n    e = ev[a:b]; print(lab, e.groupby(\"zone\").fwd12.agg(['count','median']).round(3).to_dict())\nprint(cur); print(pd.DataFrame(comps)[[\"signal\",\"score\",\"reading\"]]); print(pd.DataFrame(bk))\n", "make_levels.py": "import sys, json, pandas as pd, numpy as np\nsrc_csv, fgi_csv, outdir = sys.argv[1], sys.argv[2], sys.argv[3]\ncode = open(__file__).read()\nD = pd.read_csv(src_csv, parse_dates=['date']).set_index('date')\nd = D.close; asof = d.index[-1].strftime('%Y-%m-%d'); price = float(d.iloc[-1])\nmeta = [{\"label\": \"make_levels.py\", \"value\": code, \"type\": \"code\", \"lang\": \"python\"},\n        {\"label\": \"Input\", \"value\": \"btc-usd-daily.csv (Bitstamp, github.com/rcaljouw/btc-price-history); btc_with_fgi_4h.csv (Fear & Greed from alternative.me via github.com/MetalGrey/btc-fgi-daily-2020)\"},\n        {\"label\": \"Data up to\", \"value\": asof}]\ndef dump(name, rows): json.dump({\"rows\": rows, \"meta\": meta}, open(f\"{outdir}/{name}.json\", \"w\"))\n# ---------- key levels ----------\nlv = []\nath_i = D.high.idxmax(); lv.append((\"All-time high\", float(D.high.max()), \"Peak on \" + ath_i.strftime('%-d %b %Y'), \"Peak\"))\ny = D.loc[d.index[-1] - pd.Timedelta(days=365):]\nlv.append((\"52-week high\", float(y.high.max()), \"Highest price in the last year, \" + y.high.idxmax().strftime('%b %Y'), \"Range\"))\nlv.append((\"52-week low\", float(y.low.min()), \"Lowest price in the last year, \" + y.low.idxmin().strftime('%b %Y'), \"Range\"))\nw = d.resample('W-SUN').last()\nlv.append((\"200-week average\", float(w.rolling(200).mean().iloc[-1]), \"Long-run average; has marked most bear-market floors\", \"Average\"))\nlv.append((\"200-day average\", float(d.rolling(200).mean().iloc[-1]), \"The main trend line\", \"Average\"))\nlv.append((\"20-week average\", float(w.rolling(20).mean().iloc[-1]), \"Medium-term trend line\", \"Average\"))\n# volume profile, last 2 years: USD volume in 2.5% log-price bins, using each day's typical price\nv2 = D.loc[d.index[-1] - pd.Timedelta(days=730):].copy()\nv2['tp'] = (v2.high + v2.low + v2.close) / 3; v2['usd'] = v2.volume * v2.tp\nedges = np.exp(np.arange(np.log(v2.low.min()), np.log(v2.high.max()) + 0.025, 0.025))\nv2['bin'] = pd.cut(v2.tp, edges)\nprof = v2.groupby('bin', observed=True).usd.sum().sort_values(ascending=False)\npicked = []\nfor b in prof.index:\n    mid = float(np.sqrt(b.left * b.right))\n    if all(abs(np.log(mid / p)) > 0.08 for p in picked): picked.append(mid)\n    if len(picked) == 3: break\nfor i, p in enumerate(sorted(picked)):\n    lv.append((f\"High-volume zone\", p, \"One of the 3 busiest trading price zones over the last 2 years (Bitstamp volume)\", \"Volume\"))\nrows = []\nfor name, val, note, kind in lv:\n    rows.append({\"level\": name if name != \"High-volume zone\" else f\"High-volume zone ~${val/1000:.0f}k\", \"price\": round(val), \"kind\": kind,\n                 \"dist_pct\": round(100 * (val / price - 1), 1), \"side\": \"Above\" if val > price else \"Below\", \"note\": note})\nrows.sort(key=lambda r: -r[\"price\"])\nrows.append({\"level\": \"Current price\", \"price\": round(price), \"kind\": \"Now\", \"dist_pct\": 0.0, \"side\": \"Now\", \"note\": \"Close on \" + asof})\nrows.sort(key=lambda r: -r[\"price\"])\ndump(\"levels\", rows)\n# ---------- Fear & Greed ----------\nf = pd.read_csv(fgi_csv, parse_dates=['timestamp'])\nf = f.dropna(subset=['Fear & Greed Index']).set_index('timestamp').sort_index()\nfd = f['Fear & Greed Index'].astype(float).resample('D').last().dropna()\nfd = fd[fd.index <= d.index[-1] + pd.Timedelta(days=1)]\ncur = float(fd.iloc[-1]); cur_date = fd.index[-1].strftime('%Y-%m-%d')\ndef lab(v): return \"Extreme fear\" if v < 25 else \"Fear\" if v < 46 else \"Neutral\" if v < 55 else \"Greed\" if v < 76 else \"Extreme greed\"\ndump(\"fgi_now\", [{\"index\": round(cur), \"label\": lab(cur), \"date\": cur_date, \"avg_30d\": round(float(fd.iloc[-30:].mean())), \"since\": fd.index[0].strftime('%Y-%m-%d')}])\nj = pd.DataFrame({\"fgi\": fd}).join(d.rename('close'), how='inner')\nj['fwd12'] = j.close.shift(-84) / j.close - 1   # 12 weeks ahead\nwk = j.resample('W-SUN').last()                 # one sample a week to cut overlap\nfh = [{\"week\": (i - pd.Timedelta(days=6)).strftime('%Y-%m-%d'), \"fgi\": round(float(r.fgi)), \"close\": round(float(r.close))} for i, r in wk.dropna(subset=['fgi', 'close']).iterrows()]\ndump(\"fgi_history\", fh)\nev = wk.dropna(subset=['fwd12']); ev = ev.assign(z=ev.fgi.map(lab))\nzr = []\nfor z in [\"Extreme fear\", \"Fear\", \"Neutral\", \"Greed\", \"Extreme greed\"]:\n    e = ev[ev.z == z]\n    zr.append({\"mood\": z, \"weeks\": int(len(e)), \"median_12w_pct\": round(100 * float(e.fwd12.median()), 1), \"up_12w_pct\": round(100 * float((e.fwd12 > 0).mean()))})\nzr.append({\"mood\": \"All weeks (baseline)\", \"weeks\": int(len(ev)), \"median_12w_pct\": round(100 * float(ev.fwd12.median()), 1), \"up_12w_pct\": round(100 * float((ev.fwd12 > 0).mean()))})\ndump(\"fgi_zones\", zr)\n# split-half robustness check (printed only)\nfor a, b in ((\"2020\", \"2022\"), (\"2023\", \"2026\")):\n    e = ev[a:b]; print(a, b, e.groupby('z').fwd12.agg(['count', 'median']).round(3).to_dict())\nprint(pd.DataFrame(rows)[[\"level\", \"price\", \"dist_pct\"]]); print(cur, lab(cur)); print(pd.DataFrame(zr))\n", "make_extras.py": "import sys, json, pandas as pd, numpy as np\nsrc_csv, gauge_csv, outdir = sys.argv[1], sys.argv[2], sys.argv[3]\ncode = open(__file__).read()\nd = pd.read_csv(src_csv, parse_dates=['date']).set_index('date').close\ng = pd.read_csv(gauge_csv, parse_dates=['date']).set_index('date')\nasof = d.index[-1].strftime('%Y-%m-%d'); price = float(d.iloc[-1])\nmeta = [{\"label\": \"make_extras.py\", \"value\": code, \"type\": \"code\", \"lang\": \"python\"},\n        {\"label\": \"Input\", \"value\": \"btc-usd-daily.csv (Bitstamp) and gauge_daily.csv (from make_gauge.py)\"},\n        {\"label\": \"Data up to\", \"value\": asof}]\ndef dump(name, rows): json.dump({\"rows\": rows, \"meta\": meta}, open(f\"{outdir}/{name}.json\", \"w\"))\ndef zone(s): return \"Strong sell\" if s <= -60 else \"Sell\" if s <= -20 else \"Neutral\" if s < 20 else \"Buy\" if s < 60 else \"Strong buy\"\nMULT = {\"Strong sell\": 0.25, \"Sell\": 0.5, \"Neutral\": 1.0, \"Buy\": 1.5, \"Strong buy\": 2.0}\n# ---------- smart buying: buy on the first day of each month, using the gauge as of the day before ----------\ndef run(start, col):\n    days = d[start:].groupby(d[start:].index.to_period('M')).head(1).index\n    spent = btc = 0.0\n    for t in days:\n        m = 1.0 if col is None else MULT[zone(g[col].shift(1).loc[t])]\n        amt = 100 * m; spent += amt; btc += amt / d.loc[t]\n    return spent, btc\ndca = []\nfor per, start in ((\"2014\u2013now\", \"2014-01-01\"), (\"2020\u2013now\", \"2020-01-01\")):\n    for name, col in ((\"Same amount every month\", None), (\"More when gauge says Buy\", \"score\"), (\"More when Value says Buy\", \"value\")):\n        spent, btc = run(start, col)\n        dca.append({\"plan\": name, \"period\": per, \"spent\": round(spent), \"btc\": round(btc, 4), \"avg_cost\": round(spent / btc),\n                    \"value_now\": round(btc * price), \"multiple\": round(btc * price / spent, 2)})\ndump(\"dca\", dca)\n# ---------- drawdowns: every fall of 50%+ from a peak ----------\npeak = d.cummax(); dd = d / peak - 1\nfalls = []; in_fall = False\nfor t, v in dd.items():\n    if not in_fall and v <= -0.5: in_fall = True; st = t\n    if in_fall and v == 0:\n        seg = dd[st:t]; lo = seg.idxmin()\n        pk = d[:st].idxmax()\n        falls.append({\"fall\": (f\"{pk.year}\" if pk.year == lo.year else f\"{pk.year}\u2013{lo.year}\"), \"peak_date\": pk.strftime('%b %Y'), \"low_date\": lo.strftime('%b %Y'), \"drop_pct\": round(100 * float(seg.min())), \"status\": \"Recovered\"})\n        in_fall = False\nif in_fall or dd.iloc[-1] < -0.3:\n    st = d[:dd.index[-1]][dd == 0].index[-1]; seg = dd[st:]; lo = seg.idxmin()\n    falls.append({\"fall\": f\"{st.year}\u2013now\", \"peak_date\": st.strftime('%b %Y'), \"low_date\": lo.strftime('%b %Y'), \"drop_pct\": round(100 * float(seg.min())), \"status\": \"Ongoing\"})\ndump(\"drawdowns\", falls)\n# ---------- halving cycle clock ----------\nhalvings = [(\"2012\", \"2012-11-28\"), (\"2016\", \"2016-07-09\"), (\"2020\", \"2020-05-11\"), (\"2024\", \"2024-04-20\")]\ncyc = []; summ = []\nfor name, h in halvings:\n    h = pd.Timestamp(h); base = float(d.loc[h])\n    seg = d[h:h + pd.Timedelta(days=1460)]\n    for day in range(0, len(seg), 7):\n        cyc.append({\"cycle\": name, \"day\": day, \"multiple\": round(float(seg.iloc[day] / base), 3)})\n    if name == \"2024\": cyc.append({\"cycle\": name, \"day\": len(seg) - 1, \"multiple\": round(float(seg.iloc[-1] / base), 3)})\n    pk = seg.idxmax()\n    summ.append({\"cycle\": name, \"halving_price\": round(base), \"peak_day\": int((pk - h).days), \"peak_multiple\": round(float(seg.max() / base), 1),\n                 \"day_now_equiv\": int(len(seg) - 1) if name == \"2024\" else None,\n                 \"multiple_at_same_day\": round(float(seg.iloc[min(len(d[pd.Timestamp('2024-04-20'):]) - 1, len(seg) - 1)] / base), 2)})\ndump(\"cycles\", cyc); dump(\"cycle_summary\", summ)\nprint(pd.DataFrame(dca)); print(pd.DataFrame(falls)); print(pd.DataFrame(summ))\n"}
btc, fgi, out = sys.argv[1], sys.argv[2], sys.argv[3]
prev = sys.argv[4] if len(sys.argv) > 4 else None
os.makedirs(out, exist_ok=True)
sd = os.path.join(os.path.dirname(os.path.abspath(out)), "kit_scripts"); os.makedirs(sd, exist_ok=True)
for n, code in SCRIPTS.items(): open(os.path.join(sd, n), "w").write(code)
run = lambda *a: subprocess.run([sys.executable, "-I", *a], check=True, stdout=subprocess.DEVNULL)
run(os.path.join(sd, "make_dash_data.py"), btc, out)
run(os.path.join(sd, "make_gauge.py"), btc, out)
run(os.path.join(sd, "make_levels.py"), btc, fgi, out)
run(os.path.join(sd, "make_extras.py"), btc, os.path.join(out, "gauge_daily.csv"), out)
rows = lambda d, n: json.load(open(os.path.join(d, n + ".json")))["rows"]
alerts = []
if prev:
    def safe(n):
        try: return rows(prev, n)
        except Exception: return None
    old = safe("signals")
    if old:
        o = {r["rule"]: r["state"] for r in old}
        for r in rows(out, "signals"):
            if r["rule"] in o and o[r["rule"]] != r["state"]: alerts.append(f"{r['rule']} flipped {o[r['rule']]} -> {r['state']}")
    old = safe("gauge_now")
    if old:
        o = {r["gauge"]: r["zone"] for r in old}
        for r in rows(out, "gauge_now"):
            if r["gauge"] in o and o[r["gauge"]] != r["zone"]: alerts.append(f"{r['gauge']} gauge moved {o[r['gauge']]} -> {r['zone']} (score {r['score']})")
    old = safe("levels")
    if old:
        o = {r["level"]: r["side"] for r in old}
        for r in rows(out, "levels"):
            if r["level"] in ("200-week average", "200-day average", "20-week average", "52-week low") and r["level"] in o and o[r["level"]] != r["side"]:
                alerts.append(f"Price crossed the {r['level']} (now {'below' if r['side'] == 'Above' else 'above'} it, level ${r['price']:,})")
    old = safe("fgi_now")
    if old and old[0]["label"] != rows(out, "fgi_now")[0]["label"]:
        alerts.append(f"Fear & Greed moved {old[0]['label']} -> {rows(out, 'fgi_now')[0]['label']}")
g = {r["gauge"]: r for r in rows(out, "gauge_now")}; s = rows(out, "signals"); f = rows(out, "fgi_now")[0]
summary = (f"BTC ${s[0]['price']:,} (close {s[0]['asof']}). Gauge {g['Overall']['zone']} ({g['Overall']['score']:+}): trend {g['Trend']['zone']}, value {g['Value']['zone']}. "
           f"{sum(r['in'] for r in s)}/5 trend rules IN. Fear & Greed {f['index']} ({f['label']}).")
open(os.path.join(out, "alerts.txt"), "w").write("\n".join(alerts))
print("SUMMARY:", summary)
print("ALERTS:", "; ".join(alerts) if alerts else "none")
